<script>
(function() {
  function ensureForm() {
    var container = document.querySelector('.contact-grid-two-col');
    if (container && !document.getElementById('contactPageForm')) {
      var formCol = document.createElement('div');
      formCol.className = 'contact-form-col';
      formCol.innerHTML = `
        <div class="contact-form-card">
          <div class="form-header">
            <h2 style="font-family: var(--font-serif, Georgia, serif); font-size: 26px; color: #3c183d; margin-bottom: 6px;">Send an Enquiry</h2>
            <p style="color: #665267; font-size: 14.5px; margin-bottom: 20px;">Fill in your details below and our team will connect with you.</p>
          </div>

          <div id="contactFormStatus" style="display:none;" class="contact-alert"></div>

          <form action="/enquiry/store" method="POST" id="contactPageForm" class="contact-form-body">
            <input type="hidden" name="_token" value="${(document.querySelector('meta[name="csrf-token"]') || {}).content || '{{ csrf_token() }}'}">
            <input type="hidden" name="source_page" value="contact_page">

            <div class="form-group">
              <label for="c_name">Full Name <span class="req">*</span></label>
              <input type="text" id="c_name" name="name" required placeholder="Enter your full name" class="form-ctrl">
            </div>

            <div class="form-row-2">
              <div class="form-group">
                <label for="c_phone">Phone / WhatsApp <span class="req">*</span></label>
                <input type="tel" id="c_phone" name="phone" required placeholder="e.g. +91 9876543210" class="form-ctrl">
              </div>
              <div class="form-group">
                <label for="c_email">Email Address</label>
                <input type="email" id="c_email" name="email" placeholder="e.g. name@example.com" class="form-ctrl">
              </div>
            </div>

            <div class="form-row-2">
              <div class="form-group">
                <label for="c_guidance">Guidance / Service</label>
                <select id="c_guidance" name="guidance_with" class="form-ctrl form-select-ctrl">
                  <option value="General Consultation">General Consultation</option>
                  <option value="Mind Training & Guidance">Mind Training & Guidance</option>
                  <option value="Numerology & Vastu">Numerology & Vastu</option>
                  <option value="Astrology Assessment">Astrology Assessment</option>
                  <option value="Personalised Hand Holding Program">Personalised Hand Holding Program</option>
                </select>
              </div>
              <div class="form-group">
                <label for="c_location">Your Location</label>
                <input type="text" id="c_location" name="based_in" placeholder="e.g. Delhi, India" class="form-ctrl">
              </div>
            </div>

            <div class="form-group">
              <label for="c_message">Your Message</label>
              <textarea id="c_message" name="message" rows="3" placeholder="Write your question or thoughts..." class="form-ctrl form-textarea-ctrl"></textarea>
            </div>

            <button type="submit" class="button button-primary contact-submit-btn" style="width: 100%; border-radius: 30px; justify-content: center; font-weight: 700;">
              <span>Send Message</span>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M5 12h14M12 5l7 7-7 7"></path></svg>
            </button>
          </form>
        </div>
      `;
      container.appendChild(formCol);
    }
    bindForm();
  }

  function bindForm() {
    var form = document.getElementById('contactPageForm');
    var statusDiv = document.getElementById('contactFormStatus');
    if (form && !form.dataset.bound) {
      form.dataset.bound = 'true';
      form.addEventListener('submit', function(e) {
        e.preventDefault();
        var btn = form.querySelector('button[type="submit"]');
        var originalBtnText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span>Sending...</span>';
        
        var formData = new FormData(form);
        
        fetch(form.action, {
          method: 'POST',
          body: formData,
          headers: {
            'X-Requested-With': 'XMLHttpRequest',
            'Accept': 'application/json'
          }
        })
        .then(function(res) { return res.json(); })
        .then(function(data) {
          btn.disabled = false;
          btn.innerHTML = originalBtnText;
          if (statusDiv) {
            statusDiv.style.display = 'flex';
            if (data.success) {
              statusDiv.className = 'contact-alert contact-alert-success';
              statusDiv.innerHTML = '<span>' + (data.message || 'Thank you! Your enquiry has been received.') + '</span>';
              form.reset();
            } else {
              statusDiv.className = 'contact-alert contact-alert-error';
              statusDiv.innerHTML = '<span>' + (data.message || 'Error submitting form. Please try again.') + '</span>';
            }
          }
        })
        .catch(function(err) {
          btn.disabled = false;
          btn.innerHTML = originalBtnText;
          if (statusDiv) {
            statusDiv.style.display = 'flex';
            statusDiv.className = 'contact-alert contact-alert-error';
            statusDiv.innerHTML = '<span>An unexpected error occurred. Please try again.</span>';
          }
        });
      });
    }
  }

  document.addEventListener('DOMContentLoaded', function() {
    ensureForm();
    setTimeout(ensureForm, 100);
    setTimeout(ensureForm, 500);
    setTimeout(ensureForm, 1500);
  });
  window.addEventListener('load', ensureForm);
})();
</script>


<script>
(function() {
  function ensureForm() {
    var container = document.querySelector('.contact-grid-two-col');
    if (container && !document.getElementById('contactPageForm')) {
      var formCol = document.createElement('div');
      formCol.className = 'contact-form-col';
      formCol.innerHTML = `
        <div class="contact-form-card">
          <div class="form-header">
            <h2 style="font-family: var(--font-serif, Georgia, serif); font-size: 26px; color: #3c183d; margin-bottom: 6px;">Send an Enquiry</h2>
            <p style="color: #665267; font-size: 14.5px; margin-bottom: 20px;">Fill in your details below and our team will connect with you.</p>
          </div>

          <div id="contactFormStatus" style="display:none;" class="contact-alert"></div>

          <form action="/enquiry/store" method="POST" id="contactPageForm" class="contact-form-body" novalidate>
            <input type="hidden" name="_token" value="${(document.querySelector('meta[name="csrf-token"]') || {}).content || '{{ csrf_token() }}'}">
            <input type="hidden" name="source_page" value="contact_page">

            <div class="form-group">
              <label for="c_name">Full Name <span class="req">*</span></label>
              <input type="text" id="c_name" name="name" required placeholder="Enter your full name" class="form-ctrl">
            </div>

            <div class="form-row-2">
              <div class="form-group">
                <label for="c_phone">Phone / WhatsApp <span class="req">*</span></label>
                <input type="tel" id="c_phone" name="phone" required placeholder="e.g. 9876543210" class="form-ctrl">
              </div>
              <div class="form-group">
                <label for="c_email">Email Address</label>
                <input type="email" id="c_email" name="email" placeholder="e.g. name@example.com" class="form-ctrl">
              </div>
            </div>

            <div class="form-row-2">
              <div class="form-group">
                <label for="c_guidance">Guidance / Service</label>
                <select id="c_guidance" name="guidance_with" class="form-ctrl form-select-ctrl">
                  <option value="General Consultation">General Consultation</option>
                  <option value="Mind Training & Guidance">Mind Training & Guidance</option>
                  <option value="Numerology & Vastu">Numerology & Vastu</option>
                  <option value="Astrology Assessment">Astrology Assessment</option>
                  <option value="Personalised Hand Holding Program">Personalised Hand Holding Program</option>
                </select>
              </div>
              <div class="form-group">
                <label for="c_location">Your Location</label>
                <input type="text" id="c_location" name="based_in" placeholder="e.g. Delhi, India" class="form-ctrl">
              </div>
            </div>

            <div class="form-group">
              <label for="c_message">Your Message</label>
              <textarea id="c_message" name="message" rows="3" placeholder="Write your question or thoughts..." class="form-ctrl form-textarea-ctrl"></textarea>
            </div>

            <button type="submit" class="button button-primary contact-submit-btn" style="width: 100%; border-radius: 30px; justify-content: center; font-weight: 700;">
              <span>Send Message</span>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M5 12h14M12 5l7 7-7 7"></path></svg>
            </button>
          </form>
        </div>
      `;
      container.appendChild(formCol);
    }
    bindForm();
  }

  function showError(input, msg) {
    var group = input.closest('.form-group');
    if (!group) return;
    var errTag = group.querySelector('.input-error-msg');
    if (!errTag) {
      errTag = document.createElement('div');
      errTag.className = 'input-error-msg';
      group.appendChild(errTag);
    }
    errTag.textContent = msg;
    input.style.borderColor = '#d9381e';
  }

  function clearError(input) {
    var group = input.closest('.form-group');
    if (!group) return;
    var errTag = group.querySelector('.input-error-msg');
    if (errTag) errTag.remove();
    input.style.borderColor = 'rgba(60, 24, 61, 0.18)';
  }

  function bindForm() {
    var form = document.getElementById('contactPageForm');
    var statusDiv = document.getElementById('contactFormStatus');
    if (form && !form.dataset.bound) {
      form.dataset.bound = 'true';

      form.querySelectorAll('.form-ctrl').forEach(function(input) {
        input.addEventListener('input', function() { clearError(input); });
      });

      form.addEventListener('submit', function(e) {
        e.preventDefault();
        
        var nameInput = document.getElementById('c_name');
        var phoneInput = document.getElementById('c_phone');
        var emailInput = document.getElementById('c_email');
        var isValid = true;

        if (nameInput) {
          clearError(nameInput);
          if (!nameInput.value.trim() || nameInput.value.trim().length < 2) {
            showError(nameInput, 'Please enter your full name (at least 2 letters).');
            isValid = false;
          }
        }

        if (phoneInput) {
          clearError(phoneInput);
          var cleanPhone = phoneInput.value.replace(/[^0-9]/g, '');
          if (!phoneInput.value.trim() || cleanPhone.length < 10) {
            showError(phoneInput, 'Please enter a valid 10-digit phone or WhatsApp number.');
            isValid = false;
          }
        }

        if (emailInput && emailInput.value.trim()) {
          clearError(emailInput);
          var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailRegex.test(emailInput.value.trim())) {
            showError(emailInput, 'Please enter a valid email address (e.g. name@example.com).');
            isValid = false;
          }
        }

        if (!isValid) {
          if (statusDiv) {
            statusDiv.style.display = 'flex';
            statusDiv.className = 'contact-alert contact-alert-error';
            statusDiv.innerHTML = '<span>Please fix the highlighted errors in the form before submitting.</span>';
          }
          return;
        }
        
        var btn = form.querySelector('button[type="submit"]');
        var originalBtnText = btn.innerHTML;
        btn.disabled = true;
        btn.innerHTML = '<span>Sending...</span>';
        
        var formData = new FormData(form);
        
        fetch(form.action, {
          method: 'POST',
          body: formData,
          headers: {
            'X-Requested-With': 'XMLHttpRequest',
            'Accept': 'application/json'
          }
        })
        .then(function(res) { return res.json(); })
        .then(function(data) {
          btn.disabled = false;
          btn.innerHTML = originalBtnText;
          if (statusDiv) {
            statusDiv.style.display = 'flex';
            if (data.success) {
              statusDiv.className = 'contact-alert contact-alert-success';
              statusDiv.innerHTML = '<span>' + (data.message || 'Thank you! Your enquiry has been received.') + '</span>';
              form.reset();
            } else {
              statusDiv.className = 'contact-alert contact-alert-error';
              statusDiv.innerHTML = '<span>' + (data.message || 'Error submitting form.') + '</span>';
              if (data.errors) {
                if (data.errors.name && nameInput) showError(nameInput, data.errors.name[0]);
                if (data.errors.phone && phoneInput) showError(phoneInput, data.errors.phone[0]);
                if (data.errors.email && emailInput) showError(emailInput, data.errors.email[0]);
              }
            }
          }
        })
        .catch(function(err) {
          btn.disabled = false;
          btn.innerHTML = originalBtnText;
          if (statusDiv) {
            statusDiv.style.display = 'flex';
            statusDiv.className = 'contact-alert contact-alert-error';
            statusDiv.innerHTML = '<span>An unexpected error occurred. Please try again.</span>';
          }
        });
      });
    }
  }

  document.addEventListener('DOMContentLoaded', function() {
    ensureForm();
    setTimeout(ensureForm, 100);
    setTimeout(ensureForm, 500);
    setTimeout(ensureForm, 1500);
  });
  window.addEventListener('load', ensureForm);
})();
</script>

